# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: render
def render(xs, factor=10):
    return [v * factor for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(emit(render(intake(fold(sift(raw))))))

